/**
 * Verifies app/utils/openskill.ts against reference vectors generated by the
 * real openskill Python package. Run in prebuild; exits non-zero on divergence.
 *
 * Regenerate the fixture with:
 *   uv venv && uv pip install openskill
 *   .venv/bin/python scripts/gen-openskill-reference.py > scripts/openskill-reference.json
 */
import { readFileSync } from 'node:fs'
import { build } from 'esbuild'
import { pathToFileURL } from 'node:url'

const TOL = 1e-6

const bundle = await build({
  entryPoints: ['app/utils/openskill.ts'],
  bundle: true, write: false, format: 'esm', platform: 'neutral'
})
const code = bundle.outputFiles[0].text
const mod = await import(`data:text/javascript;base64,${Buffer.from(code).toString('base64')}`)

const ref = JSON.parse(readFileSync('scripts/openskill-reference.json', 'utf8'))
let checks = 0, failures = []

const MODELS = {
  plackett_luce: 'plackett_luce',
  thurstone_mosteller: 'thurstone_mosteller',
  bradley_terry: 'bradley_terry'
}

for (const [key, modelName] of Object.entries(MODELS)) {
  for (const c of ref[key]) {
    const teams = c.input.map(t => t.map(([mu, sigma]) => ({ mu, sigma })))
    const got = mod.rate(teams, c.ranks, modelName)
    c.output.forEach((team, ti) => {
      team.forEach(([mu, sigma], pi) => {
        const g = got[ti][pi]
        checks += 2
        if (Math.abs(g.mu - mu) > TOL)
          failures.push(`${key}/${c.name} team${ti} p${pi} mu: got ${g.mu} want ${mu}`)
        if (Math.abs(g.sigma - sigma) > TOL)
          failures.push(`${key}/${c.name} team${ti} p${pi} sigma: got ${g.sigma} want ${sigma}`)
      })
    })
  }
  // predict_win, two teams
  const want = ref[`${key}_predict_win`]
  const got = mod.predictWin([[{ mu: 25.0, sigma: 8.333 }], [{ mu: 30.0, sigma: 4.0 }]])
  want.forEach((p, i) => {
    checks++
    if (Math.abs(got[i] - p) > TOL) failures.push(`${key}/predict_win[${i}]: got ${got[i]} want ${p}`)
  })

  // predict_win, four teams — a different branch, and an MCP tool.
  const wantMulti = ref[`${key}_predict_win_multi`]
  const gotMulti = mod.predictWin([
    [{ mu: 25.0, sigma: 8.333 }],
    [{ mu: 30.0, sigma: 4.0 }, { mu: 20.0, sigma: 6.0 }],
    [{ mu: 27.0, sigma: 5.0 }],
    [{ mu: 22.0, sigma: 7.5 }]
  ])
  wantMulti.forEach((p, i) => {
    checks++
    if (Math.abs(gotMulti[i] - p) > TOL)
      failures.push(`${key}/predict_win_multi[${i}]: got ${gotMulti[i]} want ${p}`)
  })
}

// ordinal is exposed as an MCP tool and had no vector of its own.
for (const o of ref.ordinal) {
  checks++
  const got = mod.ordinal({ mu: o.mu, sigma: o.sigma }, o.z)
  if (Math.abs(got - o.value) > TOL)
    failures.push(`ordinal(mu=${o.mu}, sigma=${o.sigma}, z=${o.z}): got ${got} want ${o.value}`)
}

if (failures.length) {
  console.error(`\n✖ openskill port diverges from the library (${failures.length}/${checks} checks failed):\n`)
  failures.slice(0, 12).forEach(f => console.error('   ' + f))
  process.exit(1)
}
console.log(`✔ openskill port matches the library on all ${checks} checks (tol ${TOL})`)
